CREATE TABLE IF NOT EXISTS fondo_caja_autorizado (id UUID PRIMARY KEY, finca_id UUID NOT NULL REFERENCES fincas(id), tipo VARCHAR(30) NOT NULL CHECK (tipo IN ('CAMBIO','PAGOS_MENORES','NOMINA','POR_DEPOSITAR')), importe_autorizado DOUBLE PRECISION NOT NULL CHECK (importe_autorizado >= 0), observaciones VARCHAR(1000), activo BOOLEAN NOT NULL DEFAULT TRUE, CONSTRAINT uq_fondo_caja_finca_tipo UNIQUE(finca_id,tipo));
CREATE SEQUENCE IF NOT EXISTS acta_responsabilidad_caja_numero_seq START WITH 1;
CREATE TABLE IF NOT EXISTS acta_responsabilidad_caja (id UUID PRIMARY KEY, numero BIGINT NOT NULL UNIQUE DEFAULT nextval('acta_responsabilidad_caja_numero_seq'), finca_id UUID NOT NULL REFERENCES fincas(id), custodio_id UUID, custodio_nombre VARCHAR(150) NOT NULL, usuario_emisor_id UUID, fecha_inicio TIMESTAMP NOT NULL, fecha_cierre TIMESTAMP, estado VARCHAR(20) NOT NULL CHECK(estado IN ('ACTIVA','CERRADA')), observaciones VARCHAR(1000));
CREATE UNIQUE INDEX IF NOT EXISTS uq_acta_responsabilidad_caja_activa ON acta_responsabilidad_caja(finca_id) WHERE estado='ACTIVA';
CREATE TABLE IF NOT EXISTS incidencia_arqueo_caja (id UUID PRIMARY KEY, arqueo_caja_id UUID NOT NULL UNIQUE REFERENCES arqueo_caja(id), finca_id UUID NOT NULL REFERENCES fincas(id), tipo VARCHAR(20) NOT NULL CHECK(tipo IN ('FALTANTE','SOBRANTE')), importe DOUBLE PRECISION NOT NULL CHECK(importe > 0), expediente VARCHAR(100) NOT NULL, descripcion VARCHAR(1000) NOT NULL, estado VARCHAR(20) NOT NULL CHECK(estado IN ('PENDIENTE','EN_REVISION','APROBADA','RESUELTA','RECHAZADA')), creado_por_id UUID, aprobado_por_id UUID, fecha_creacion TIMESTAMP NOT NULL, fecha_resolucion TIMESTAMP, observaciones VARCHAR(1000));
CREATE INDEX IF NOT EXISTS idx_incidencia_arqueo_caja_finca ON incidencia_arqueo_caja(finca_id,fecha_creacion DESC);
